from __future__ import annotations

from datetime import date

import polars as pl
from src.backtest.strategy import MarketView, Signal, Strategy


class RangeCompression(Strategy):
    rationale = (
        "Range compression indicates reduced volatility and potentially increased price "
        "consensus. We can identify such stocks by looking at the standard deviation of daily "
        "price movements over a lookback period. Low dispersion suggests that prices are "
        "converging, making these stocks attractive for entry."
    )

    def __init__(self, window: int = 20) -> None:
        self._window = window

    def generate(self, view: MarketView) -> Signal:
        stamp = _latest_visible(view)
        history = view.history(lookback=self._window)
        if history.height < self._window:
            return Signal(information_available_at=stamp, weights={})

        picks: list[str] = []
        for symbol in view.symbols:
            if symbol not in history["symbol"].to_list():
                continue
            daily_changes = (
                history.lazy()
                .filter(pl.col("symbol") == symbol)
                .select(
                    (pl.col("adj_close") - pl.col("adj_close").shift(1))
                    .abs()
                    .alias("range_change")
                )
                .collect()["range_change"]
            )
            if daily_changes.height < self._window:
                continue
            std_dev = float(daily_changes.std())
            if std_dev <= 0.2:  # Adjust this threshold based on empirical analysis
                picks.append(symbol)

        picks = picks[:10]  # Select top 10 symbols with highest range compression
        if not picks:
            return Signal(information_available_at=stamp, weights={})
        weight = 1.0 / len(picks)
        return Signal(
            information_available_at=stamp, weights={s: weight for s in picks}
        )


def _latest_visible(view: MarketView) -> date:
    visible = view.history()
    if visible.is_empty():
        return date(1900, 1, 1)
    newest = visible["session_date"].max()
    assert isinstance(newest, date)
    return newest
